package dev.diamondtier;

import net.minecraft.client.gui.GuiGraphics;

import java.util.HashMap;
import java.util.Map;

/** The gamemode icons, stored as 16x16 pixels so no image files are needed. */
public final class ModeIcons {
    private static final int N = 16;
    private static final Map<String, int[]> ICONS = new HashMap<>();

    static {
        add("crystal", "");
        add("sword", "");
        add("axe", "");
        add("mace", "");
        add("nethpot", "");
        add("uhc", "");
        add("dsmp", "");
        add("smp", "");
        add("creator", "");
    }

    private ModeIcons() {}

    private static void add(String mode, String hex) {
        int[] px = new int[N * N];
        for (int i = 0; i < px.length; i++) px[i] = (int) Long.parseLong(hex.substring(i * 8, i * 8 + 8), 16);
        ICONS.put(mode, px);
    }

    public static boolean has(String mode) {
        return ICONS.containsKey(mode);
    }

    /** Draws the icon with its top-left corner at (x, y), size x size units. */
    public static void draw(GuiGraphics g, String mode, int x, int y, float size) {
        int[] px = ICONS.get(mode);
        if (px == null) return;
        g.pose().pushMatrix();
        g.pose().translate(x, y);
        float s = size / N;
        g.pose().scale(s, s);
        for (int row = 0; row < N; row++) {
            int col = 0;
            while (col < N) {
                int c = px[row * N + col];
                if ((c >>> 24) == 0) { col++; continue; }
                int end = col + 1;
                while (end < N && px[row * N + end] == c) end++;
                g.fill(col, row, end, row + 1, c);
                col = end;
            }
        }
        g.pose().popMatrix();
    }
}
